set-variable.value:
#[(vars.responses default []) ++ [{
                            status: 'FAIL',
                            description: 'No Capacities',
                            capacities: null
                          }]]

ee:message.ee:set-payload:
%dw 2.0
output application/json

---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "GET",
	path: "/unifiedPortalConf",
	body: {},
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client-secret'),
	"client_id" : p('mongo-db-sapi.security.client-id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{
		nombre: p('mongo-db-sapi.nombre-franja')
	},
	uriParameters:{

	}
}

%dw 2.0
output application/json

var caps = 
  (payload 
    filter ((item) -> item.status == "PASS" and item.capacities != null)
    flatMap ((item) -> item.capacities)) default []

var groupedByDate = caps groupBy $.date

fun obtenerValor(llave) =
    (vars.timeslot_user filter ($.Llave == llave))[0].Valor default ""


---
{
  items: groupedByDate pluck ((capacities, date) -> {
    date: date,
    areas: [
      {
        label: vars.area[0],
        timeSlots: (capacities groupBy $.time_slot) pluck ((capsByTimeSlot, timeSlot) -> {
          label: timeSlot,
          timeslot_user: obtenerValor((timeSlot) as String),
          categories: capsByTimeSlot map (c) -> {
            label: c.work_skill,
            quota: (c.quota as Number),
            used: 0
          }
        })
      }
    ]
  })
}
